import attr

from taf.ul.ue.sim.env_setup.devices.iphy_airphone_interface import (
    IphyAirphoneInterface,
)


@attr.s(cmp=False, hash=True)
class Iphy(IphyAirphoneInterface):
    def _get_taf_pdu_config(self):
        return self.configuration.pdu_port

    def _get_lmp_ip_for_taf(self) -> str:
        return self.configuration.iphy_ssh_connection_details.addr

    def _get_lmp_ip_for_ute(self) -> str:
        iphy_trs_ip = self.configuration.trs_ip
        trs_last_octet = iphy_trs_ip.split(".")[-1]
        return f"192.168.200.{int(trs_last_octet) // 2}"

    def _get_lmp_password(self) -> str:
        return self.configuration.iphy_ssh_connection_details.password

    def _set_vlan(self):
        pass
